insert into public.mortgage_programs (id, bank, name, rate, rate_note, min_down_payment_pct, reduced_down_payment_pct, reduced_down_payment_note, max_term_years, max_amount_major, max_amount_other, housing_types, note, source_url, verified_at, sort) values
  ('otbasy-nauryz', 'Отбасы банк', 'Наурыз', 9, '7% для социально уязвимых категорий, состоящих на учёте нуждающихся в жилье. После накопления 50% суммы займа ставка снижается до 3,5–5%.', 20, 10, 'Для первичного жилья с чистовой отделкой', 19, 36000000, 30000000, array['completed', 'construction_kzhk']::text[], 'Для граждан РК и кандасов. Строящееся жильё — только по договору долевого участия с гарантией единого оператора (КЖК). Точные условия уточняйте в банке.', 'https://hcsbk.kz/ru/to-get-a-loan/nauryz/', '2026-10-17', 1),
  ('otbasy-otau', 'Отбасы банк', 'Отау', 9, '7% для социально уязвимых категорий, состоящих на учёте нуждающихся в жилье. После накопления 50% суммы займа ставка снижается до 3,5–5%.', 20, null, null, 19, 36000000, 30000000, array['completed', 'construction_kzhk']::text[], 'Нужен депозит в Отбасы банке с накоплением от 1 млн ₸ и отсутствие жилья в собственности. Строящееся жильё — только с гарантией КЖК. Точные условия уточняйте в банке.', 'https://hcsbk.kz/ru/to-get-a-loan/otau/', '2026-10-17', 2)
