insert into public.data_sources (id, title, publisher, url, license, used_for, retrieved_at, note, sort) values
  ('developer-catalogs', 'Каталоги квартир на сайтах застройщиков', 'Sensata Group, BI Group, BAZIS-A', 'https://sensata.kz/projects', null, 'Цены, площади, комнатность и этажи квартир. Берём базовую цену без акций; у BAZIS-A цена посчитана как «цена за м² × площадь».', '2026-10-17', 'Небольшая выборка свободных квартир, собранная вручную. Цены меняются — уточняйте у застройщика.', 1),
  ('images', 'Планировки, фото и интерьеры', 'Sensata Group, BI Group, BAZIS-A', 'https://sensata.kz/projects', 'Права принадлежат застройщикам', 'Планировки квартир, рендеры и фото ЖК, холлы и лобби. Показываем по ссылке с сайтов застройщиков и под каждым изображением указываем источник.', '2026-10-23', 'Если застройщик уберёт изображение с сайта, вместо планировки останется наша схема по площади.', 1),
  ('registry', 'Реестр долевого строительства («Казреестр» АО «КЖК»)', 'Сводка developers.kz по официальному реестру', 'https://developers.kz/market/zhk', null, 'Схема защиты дольщиков (гарантия КЖК, разрешение акимата, участие банка), адрес и плановая дата ввода.', '2026-10-17', 'Срез реестра от 27.09.2026. Проверить объект в первоисточнике можно в eGov Mobile (Жилищный портал) или на homeportal.kz.', 2),
  ('bns', 'Цены на рынке жилья', 'Бюро национальной статистики АСПиР РК', 'https://stat.gov.kz/ru/industries/economy/prices/dynamic-tables/', 'Открытые данные', 'Средняя цена нового жилья за м² по городам — с ней сравнивается цена квартиры.', '2026-10-17', 'Данные за 2025 год. Это средние цены фактических сделок, обычно они ниже цен в объявлениях.', 3),
  ('otbasy', 'Программы «Наурыз» и «Отау»', 'Отбасы банк', 'https://hcsbk.kz/ru/to-get-a-loan/nauryz/', null, 'Ставки, первоначальный взнос, сроки и лимиты в ипотечном калькуляторе.', '2026-10-17', 'Расчёт справочный, точные условия уточняйте в банке.', 4),
  ('osm', 'OpenStreetMap', '© Участники OpenStreetMap', 'https://www.openstreetmap.org/copyright', 'ODbL', 'Карта и координаты ЖК по адресу.', '2026-10-17', 'Метки стоят на улице из адреса: дом может быть в стороне. ЖК без точного адреса на карте не показаны.', 5)
